const output = $input.item.json.output;
let parsed;

if (typeof output === 'string') {
  const jsonMatch = output.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    parsed = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in output');
  }
} else {
  parsed = output;
}

const blogId = parsed.blogId;
const topics = parsed.topics || [];

const now = new Date();
return topics.map((topic, index) => {
  const uniqueId = `${now.getTime()}_${index}`;
  return {
    json: {
      uniquePostId: uniqueId,
      blogId: blogId,
      title: topic.title,
      description: topic.description,
      labels: topic.labels,
      wordCount: topic.wordCount,
      readingTime: topic.readingTime,
      outline: topic.outline,
      codeExamples: topic.codeExamples,
      imagePrompts: topic.imagePrompts,
      visualElements: topic.visualElements,
      createdDate: now.toISOString(),
      folderPath: `/files/bloggergenerator/${uniqueId}`
    }
  };
});

// Retrieve original data from upstream node (Parse JSON Output) to bypass data loss in Execute Command
// references: Parse JSON Output
// We access all items from the Parse JSON Output node directly
const items = $("Parse JSON Output").all();
const results = [];

items.forEach(item => {
  const json = item.json;

  // Add folder paths that were created implicitly
  json.folderCreated = true;
  json.assetsPath = `${json.folderPath}/assets`;
  json.imagesPath = `${json.folderPath}/assets/images`;

  const imagePrompts = json.imagePrompts || [];

  if (imagePrompts.length === 0) {
    results.push({
      json: {
        ...json,
        imagesGenerated: 0,
        savedImages: [],
        currentPrompt: null
      }
    });
  } else {
    imagePrompts.forEach(prompt => {
      results.push({
        json: {
          ...json,
          currentPrompt: prompt,
          totalPrompts: imagePrompts.length
        }
      });
    });
  }
});

return results;

const result = $input.item.json;
const originalData = $input.item.json;

return [{ json: {
  ...originalData,
  imageSaved: result.success || false,
  imagePath: result.fullPath || '',
  imageFilename: result.filename || '',
  imageType: originalData.currentPrompt?.type || '',
  imageGenerationTime: result.timeTakenMs || 0
} }];

const items = $input.all();

if (items.length === 0) {
  return [];
}

// Group items by uniquePostId
const postGroups = {};
items.forEach(item => {
  const json = item.json;
  const postId = json.uniquePostId;
  if (!postGroups[postId]) {
    postGroups[postId] = {
      baseData: json,
      images: []
    };
  }
  if (json.imageSaved) {
    postGroups[postId].images.push({
      filename: json.imageFilename,
      type: json.imageType,
      path: json.imagePath
    });
  }
});

// Return one item per blog post
return Object.values(postGroups).map(group => ({
  json: {
    uniquePostId: group.baseData.uniquePostId,
    blogId: group.baseData.blogId,
    title: group.baseData.title,
    description: group.baseData.description,
    labels: group.baseData.labels,
    wordCount: group.baseData.wordCount,
    readingTime: group.baseData.readingTime,
    outline: group.baseData.outline,
    codeExamples: group.baseData.codeExamples,
    visualElements: group.baseData.visualElements,
    createdDate: group.baseData.createdDate,
    folderPath: group.baseData.folderPath,
    imagesGenerated: group.images.length,
    savedImages: group.images
  }
}));

const htmlContent = $json.text || $json.content || $json.response;
const filename = $json.title.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '') + '.html';
const folderPath = $json.folderPath;

const buffer = Buffer.from(htmlContent, 'utf8');

return [{ 
  json: { 
    ...$json, 
    htmlFile: folderPath + '/' + filename, 
    filename, 
    generatedContent: htmlContent 
  },
  binary: {
    data: {
      data: buffer.toString('base64'),
      mimeType: 'text/html',
      fileName: filename
    }
  }
}];

const items = $input.all();
const created = items.map((item, i) => ({
  title: item.json.title,
  uniquePostId: item.json.uniquePostId,
  folderPath: item.json.folderPath,
  htmlFile: item.json.htmlFile,
  imageCount: item.json.imagesGenerated || 0,
  response: item.json
}));
return { json: {
  message: 'All blog posts generated and saved!',
  count: created.length,
  posts: created,
  location: '/files/bloggergenerator/'
} };
